192 :     protected PointValuePair doOptimize() {
193 :         final ConvergenceChecker<PointValuePair> checker = getConvergenceChecker();
194 :         final double[] point = getStartPoint();
195 :         final GoalType goal = getGoalType();
196 :         final int n = point.length;
197 :         double[] r = computeObjectiveGradient(point);
198 :         if (goal == GoalType.MINIMIZE) {
199 :             for (int i = 0; i < n; i++) {
200 :                 r[i] = -r[i];
201 :             }
202 :         }
203 : 
204 :         // Initial search direction.
205 :         double[] steepestDescent = preconditioner.precondition(point, r);
206 :         double[] searchDirection = steepestDescent.clone();
207 : 
208 :         double delta = 0;
209 :         for (int i = 0; i < n; ++i) {
210 :             delta += r[i] * searchDirection[i];
211 :         }
212 : 
213 :         PointValuePair current = null;
214 :         int iter = 0;
215 :         int maxEval = getMaxEvaluations();
216 :         while (true) {
217 :             ++iter;
218 : 
219 :             final double objective = computeObjectiveValue(point);
220 :             PointValuePair previous = current;
221 :             current = new PointValuePair(point, objective);
222 :             if (previous != null) {
223 :                 if (checker.converged(iter, previous, current)) {
224 :                     // We have found an optimum.
225 :                     return current;
226 :                 }
227 :             }
228 : 
229 :             // Find the optimal step in the search direction.
230 :             final UnivariateFunction lsf = new LineSearchFunction(point, searchDirection);
231 :             final double uB = findUpperBound(lsf, 0, initialStep);
232 :             // XXX Last parameters is set to a value close to zero in order to
233 :             // work around the divergence problem in the "testCircleFitting"
234 :             // unit test (see MATH-439).
235 :             final double step = solver.solve(maxEval, lsf, 0, uB, 1e-15);
236 :             maxEval -= solver.getEvaluations(); // Subtract used up evaluations.
237 : 
238 :             // Validate new point.
239 :             for (int i = 0; i < point.length; ++i) {
240 :                 point[i] += step * searchDirection[i];
241 :             }
242 : 
243 :             r = computeObjectiveGradient(point);
244 :             if (goal == GoalType.MINIMIZE) {
245 :                 for (int i = 0; i < n; ++i) {
246 :                     r[i] = -r[i];
247 :                 }
248 :             }
249 : 
250 :             // Compute beta.
251 :             final double deltaOld = delta;
252 :             final double[] newSteepestDescent = preconditioner.precondition(point, r);
253 :             delta = 0;
254 :             for (int i = 0; i < n; ++i) {
255 :                 delta += r[i] * newSteepestDescent[i];
256 :             }
257 : 
258 :             final double beta;
259 :             switch (updateFormula) {
260 :             case FLETCHER_REEVES:
261 :                 beta = delta / deltaOld;
262 :                 break;
263 :             case POLAK_RIBIERE:
264 :                 double deltaMid = 0;
265 :                 for (int i = 0; i < r.length; ++i) {
266 :                     deltaMid += r[i] * steepestDescent[i];
267 :                 }
268 :                 beta = (delta - deltaMid) / deltaOld;
269 :                 break;
270 :             default:
271 :                 // Should never happen.
272 :                 throw new MathInternalError();
273 :             }
274 :             steepestDescent = newSteepestDescent;
275 : 
276 :             // Compute conjugate search direction.
277 :             if (iter % n == 0 ||
278 :                 beta < 0) {
279 :                 // Break conjugation: reset search direction.
280 :                 searchDirection = steepestDescent.clone();
281 :             } else {
282 :                 // Compute new conjugate search direction.
283 :                 for (int i = 0; i < n; ++i) {
284 :                     searchDirection[i] = steepestDescent[i] + beta * searchDirection[i];
285 :                 }
286 :             }
287 :         }
288 :     }"

