"328 :     private double findUpperBound(final UnivariateFunction f,
329 :                                   final double a, final double h) {
330 :         final double yA = f.value(a);
331 :         double yB = yA;
332 :         for (double step = h; step < Double.MAX_VALUE; step *= FastMath.max(2, yA / yB)) {
333 :             final double b = a + step;
334 :             yB = f.value(b);
335 :             if (yA * yB <= 0) {
336 :                 return b;
337 :             }
338 :         }
339 :         throw new MathIllegalStateException(LocalizedFormats.UNABLE_TO_BRACKET_OPTIMUM_IN_LINE_SEARCH);
340 :     }"

